style.css:
body {
  background: url('https://i.imgur.com/8KQlXJc.gif') repeat;
  font-family: "Comic Sans MS", cursive;
  color: yellow;
  text-align: center;
  margin: 0;
  padding: 20px;
}

h1, h2 {
  color: lime;
  text-shadow: 3px 3px 0 red;
  font-size: 32px;
  filter: glow(color=red, strength=3);
}

a:link    { color: red; text-decoration: underline; }
a:visited { color: purple; }
a:hover   { color: blue; text-decoration: blink; }
a:active  { color: fuchsia; }

hr {
  border: 1px dashed red;
  width: 80%;
}

marquee {
  background: black;
  color: white;
  font-size: 18px;
  padding: 10px;
  margin: 20px auto;
  width: 90%;
  border: 2px inset silver;
}

table {
  border: 2px ridge silver;
  margin: 20px auto;
  background: silver;
}

td, th {
  padding: 10px;
  border: 1px solid gray;
}

blink {
  font-size: 20px;
  color: fuchsia;
}
